cat > /tmp/fanin.pl << 'ENDPERL'
#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";

# Collect all .go files
my @files;
find({ wanted => sub { push @files, $File::Find::name if /\.go$/ }, no_chdir => 1 }, $root);

# Parse package name and function declarations from internal/
my @decls; # {file, pkg, recv, name, line, exported}
my %pkg_of_file;
my %pkg_dir; # dir -> pkg

for my $f (@files) {
    open my $fh, "<", $f or die $!;
    my $pkg;
    my $line = 0;
    while (my $l = <$fh>) {
        $line++;
        if (!$pkg && $l =~ /^package\s+(\w+)/) {
            $pkg = $1;
            $pkg_of_file{$f} = $pkg;
            my $dir = $f;
            $dir =~ s{/[^/]+$}{};
            $pkg_dir{$dir} = $pkg;
        }
        if ($f =~ m{/internal/} && $l =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my ($recv, $name) = ($1 // "", $2);
            $recv =~ s/\s+/ /g;
            push @decls, {
                file => $f,
                pkg => $pkg // "?",
                recv => $recv,
                name => $name,
                line => $line,
            };
        }
    }
    close $fh;
}

print "Declarations: " . scalar(@decls) . "\n";

# Read all file contents
my %content;
my %lines_of;
for my $f (@files) {
    open my $fh, "<", $f or die $!;
    local $/;
    $content{$f} = <$fh>;
    close $fh;
    $lines_of{$f} = [ split /\n/, $content{$f}, -1 ];
}

# For each declaration, count call sites
# Strategy:
# - skip init
# - package-level func (no recv):
#     same package: \bName(  but not func Name(
#     other package: \bpkg.Name(
# - method (has recv):
#     \.Name(
# This overcounts common method names; we flag those.

sub is_test {
    my ($f) = @_;
    return $f =~ /_test\.go$/;
}

sub same_pkg {
    my ($f1, $f2) = @_;
    return ($pkg_of_file{$f1} // "") eq ($pkg_of_file{$f2} // "")
        && (do { my $d1=$f1; $d1=~s{/[^/]+$}{}; my $d2=$f2; $d2=~s{/[^/]+$}{}; $d1 eq $d2 });
}

my @results;
for my $d (@decls) {
    my $name = $d->{name};
    next if $name eq "init";
    my $is_method = $d->{recv} ne "";
    my $pkg = $d->{pkg};

    my $calls_all = 0;
    my $calls_prod = 0;
    my $files_all = 0;
    my $files_prod = 0;
    my @callers;

    for my $f (@files) {
        my $text = $content{$f};
        my $count = 0;
        if ($is_method) {
            # method calls: .Name(
            while ($text =~ /\.$name\s*\(/g) {
                $count++;
            }
        } else {
            if (same_pkg($f, $d->{file})) {
                # same package: Name( but not func Name( and not func (recv) Name(
                while ($text =~ /(?<![\w.])$name\s*\(/g) {
                    $count++;
                }
                # subtract declaration
                $count-- if $count > 0;
                # also subtract if this is the decl file and we over-subtracted comments? ok
            } else {
                while ($text =~ /\b\Q$pkg\E\.$name\s*\(/g) {
                    $count++;
                }
            }
        }
        next unless $count > 0;
        # For methods, the declaration is `func (recv) Name(` not `.Name(`, so no subtract needed
        $calls_all += $count;
        $files_all++;
        push @callers, "$f:$count";
        unless (is_test($f)) {
            $calls_prod += $count;
            $files_prod++;
        }
    }

    push @results, {
        %$d,
        calls_all => $calls_all,
        calls_prod => $calls_prod,
        files_all => $files_all,
        files_prod => $files_prod,
        is_method => $is_method,
    };
}

# Sort by calls_all
my @top_all = sort { $b->{calls_all} <=> $a->{calls_all} || $a->{name} cmp $b->{name} } @results;
my @top_prod = sort { $b->{calls_prod} <=> $a->{calls_prod} || $a->{name} cmp $b->{name} } @results;

print "\n===== TOP 25 by call sites (including tests) =====\n";
printf "%-4s %-6s %-8s %-40s %-50s %s\n", "all", "prod", "files", "symbol", "recv", "file";
for my $i (0..24) {
    my $r = $top_all[$i];
    last unless $r;
    printf "%-4d %-6d %-8d %-40s %-50s %s:%d\n",
        $r->{calls_all}, $r->{calls_prod}, $r->{files_all},
        $r->{name}, $r->{recv} || "(func)", $r->{file}, $r->{line};
}

print "\n===== TOP 25 by call sites (production only) =====\n";
printf "%-4s %-6s %-8s %-40s %-50s %s\n", "prod", "all", "files", "symbol", "recv", "file";
for my $i (0..24) {
    my $r = $top_prod[$i];
    last unless $r;
    printf "%-4d %-6d %-8d %-40s %-50s %s:%d\n",
        $r->{calls_prod}, $r->{calls_all}, $r->{files_prod},
        $r->{name}, $r->{recv} || "(func)", $r->{file}, $r->{line};
}
ENDPERL
perl /tmp/fanin.pl

