# Get file list then run analyzer without File::Find
find /bench/repo -name '*.go' > /tmp/gofiles.txt
wc -l /tmp/gofiles.txt

cat > /tmp/fanin.pl << 'ENDPERL'
#!/usr/bin/env perl
use strict;
use warnings;

open my $lf, "<", "/tmp/gofiles.txt" or die $!;
my @files = grep { chomp; $_ } <$lf>;
close $lf;

my @decls;
my %pkg_of_file;

for my $f (@files) {
    open my $fh, "<", $f or die $!;
    my $pkg;
    my $line = 0;
    while (my $l = <$fh>) {
        $line++;
        if (!$pkg && $l =~ /^package\s+(\w+)/) {
            $pkg = $1;
            $pkg_of_file{$f} = $pkg;
        }
        if ($f =~ m{/internal/} && $l =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my ($recv, $name) = ($1 // "", $2);
            $recv =~ s/\s+/ /g;
            push @decls, {
                file => $f,
                pkg => $pkg // "?",
                recv => $recv,
                name => $name,
                line => $line,
            };
        }
    }
    close $fh;
}

print "Declarations: " . scalar(@decls) . " files: " . scalar(@files) . "\n";

my %content;
for my $f (@files) {
    open my $fh, "<", $f or die $!;
    local $/;
    $content{$f} = <$fh>;
    close $fh;
}

sub is_test {
    my ($f) = @_;
    return $f =~ /_test\.go$/;
}

sub same_pkg {
    my ($f1, $f2) = @_;
    my $d1 = $f1; $d1 =~ s{/[^/]+$}{};
    my $d2 = $f2; $d2 =~ s{/[^/]+$}{};
    return $d1 eq $d2;
}

my @results;
for my $d (@decls) {
    my $name = $d->{name};
    next if $name eq "init";
    my $is_method = $d->{recv} ne "";
    my $pkg = $d->{pkg};

    my $calls_all = 0;
    my $calls_prod = 0;
    my $files_all = 0;
    my $files_prod = 0;

    for my $f (@files) {
        my $text = $content{$f};
        my $count = 0;
        if ($is_method) {
            while ($text =~ /\.$name\s*\(/g) {
                $count++;
            }
        } else {
            if (same_pkg($f, $d->{file})) {
                while ($text =~ /(?<![\w.])$name\s*\(/g) {
                    $count++;
                }
                $count-- if $count > 0; # subtract declaration
            } else {
                while ($text =~ /\b\Q$pkg\E\.$name\s*\(/g) {
                    $count++;
                }
            }
        }
        next unless $count > 0;
        $calls_all += $count;
        $files_all++;
        unless (is_test($f)) {
            $calls_prod += $count;
            $files_prod++;
        }
    }

    push @results, {
        %$d,
        calls_all => $calls_all,
        calls_prod => $calls_prod,
        files_all => $files_all,
        files_prod => $files_prod,
        is_method => $is_method,
    };
}

my @top_all = sort { $b->{calls_all} <=> $a->{calls_all} || $a->{name} cmp $b->{name} } @results;
my @top_prod = sort { $b->{calls_prod} <=> $a->{calls_prod} || $a->{name} cmp $b->{name} } @results;

print "\n===== TOP 30 by call sites (including tests) =====\n";
printf "%-4s %-6s %-8s %-36s %-40s %s\n", "all", "prod", "files", "symbol", "recv", "file";
for my $i (0..29) {
    my $r = $top_all[$i];
    last unless $r;
    my $rel = $r->{file}; $rel =~ s{^/bench/repo/}{};
    printf "%-4d %-6d %-8d %-36s %-40s %s:%d\n",
        $r->{calls_all}, $r->{calls_prod}, $r->{files_all},
        $r->{name}, $r->{recv} || "(func)", $rel, $r->{line};
}

print "\n===== TOP 30 by call sites (production only) =====\n";
printf "%-4s %-6s %-8s %-36s %-40s %s\n", "prod", "all", "files", "symbol", "recv", "file";
for my $i (0..29) {
    my $r = $top_prod[$i];
    last unless $r;
    my $rel = $r->{file}; $rel =~ s{^/bench/repo/}{};
    printf "%-4d %-6d %-8d %-36s %-40s %s:%d\n",
        $r->{calls_prod}, $r->{calls_all}, $r->{files_prod},
        $r->{name}, $r->{recv} || "(func)", $rel, $r->{line};
}
ENDPERL
